const pptxgen = require('pptxgenjs');
const fs = require('fs');

async function createPresentation() {
    let pres = new pptxgen();
    pres.layout = 'LAYOUT_WIDE'; // 13.3" x 7.5"

    // Define Colors and Fonts based on theme
    const darkBg = '6D2E46'; // Berry
    const lightBg = 'ECE2D0'; // Cream
    const accentColor = '990011'; // Cherry Bold
    const textColorDark = 'ECE2D0';
    const textColorLight = '36454F'; // Charcoal Minimal for contrast

    const titleFont = { size: 44, bold: true, color: textColorDark, fontFace: 'Cambria' };
    const subTitleFont = { size: 24, color: textColorDark, fontFace: 'Calibri' };
    const sectionTitleFont = { size: 28, bold: true, color: textColorLight, fontFace: 'Cambria' };
    const bodyFont = { size: 16, color: textColorLight, fontFace: 'Calibri', margin: 0 };
    const statFont = { size: 72, bold: true, color: accentColor, fontFace: 'Cambria' };
    const statLabelFont = { size: 16, color: textColorLight, fontFace: 'Calibri' };

    // --- Slide 1: Title Slide (Dark Background) ---
    let slide1 = pres.addSlide();
    slide1.slideMaster({ title: 'Title' });
    slide1.bkgd = darkBg;
    slide1.addText('Incredible India', { x: 0.5, y: 2.5, w: '90%', align: 'center', ...titleFont });
    slide1.addText('A Presentation by TITAN', { x: 0.5, y: 3.5, w: '90%', align: 'center', ...subTitleFont });

    // --- Slide 2: Diversity & Culture (Two-Column, Light Background) ---
    let slide2 = pres.addSlide();
    slide2.bkgd = lightBg;
    slide2.addText('Diversity & Culture', { x: 0.5, y: 0.5, w: '95%', ...sectionTitleFont });

    const diversityText = "India is a land of unparalleled diversity, rich with a tapestry of languages, traditions, and faiths. With thousands of ethnic groups and hundreds of spoken languages, it is a vibrant mosaic celebrating unity in diversity.";
    slide2.addText(diversityText, { x: 0.5, y: 1.8, w: '60%', ...bodyFont, breakLine: true });
    // Placeholder for image on right (Visual element)
    slide2.addText('Visual Placeholder: Culture & Diversity', { x: '65%', y: 1.8, w: '30%', h: 4.5, align: 'center', fill: { color: 'E0E0E0' } });

    // --- Slide 3: Key Statistics (Large Callout) ---
    let slide3 = pres.addSlide();
    slide3.bkgd = lightBg;
    slide3.addText('Key Statistics', { x: 0.5, y: 0.5, w: '95%', ...sectionTitleFont });

    // Use large stats callouts
    slide3.addText('~1.4+ Billion', { x: 0.5, y: 2.0, w: '30%', align: 'center', ...statFont });
    slide3.addText('Population', { x: 0.5, y: 3.2, w: '30%', align: 'center', ...statLabelFont });

    slide3.addText('7th Largest', { x: 0.35, y: 4.0, w: '30%', align: 'center', ...statFont });
    slide3.addText('by Area (Sq Km)', { x: 0.35, y: 5.2, w: '30%', align: 'center', ...statLabelFont });

    slide3.addText('Major Economy', { x: '60%', y: 3.0, w: '35%', align: 'center', ...statFont, color: darkBg });
    slide3.addText('Global Influence', { x: '60%', y: 4.2, w: '35%', align: 'center', ...statLabelFont });

    // --- Slide 4: Landmarks (Grid Layout) ---
    let slide4 = pres.addSlide();
    slide4.bkgd = lightBg;
    slide4.addText('Iconic Landmarks', { x: 0.5, y: 0.5, w: '95%', ...sectionTitleFont });

    // 2x2 Grid placeholders
    slide4.addText('Visual: Taj Mahal', { x: 0.5, y: 1.5, w: '45%', h: 2.5, fill: { color: 'E0E0E0' }, align: 'center' });
    slide4.addText('Text: Symbol of Love', { x: 0.5, y: 4.2, w: '45%', ...bodyFont });

    slide4.addText('Visual: Diverse Landscapes', { x: '50%', y: 1.5, w: '45%', h: 2.5, fill: { color: 'E0E0E0' }, align: 'center' });
    slide4.addText('Text: Himalayas to Coastline', { x: '50%', y: 4.2, w: '45%', ...bodyFont });


    // --- Slide 5: Conclusion (Dark Background) ---
    let slide5 = pres.addSlide();
    slide5.bkgd = darkBg;
    slide5.addText('Conclusion', { x: 0.5, y: 2.5, w: '90%', align: 'center', ...titleFont, color: textColorDark });
    slide5.addText('A dynamic and thriving nation with a rich heritage and promising future.', { x: 0.5, y: 3.5, w: '90%', align: 'center', ...subTitleFont, color: textColorDark });


    const outputPath = 'C:/Users/achal/Desktop/India_Presentation.pptx';
    pres.writeFile({ fileName: outputPath });
    console.log(`Presentation saved to ${outputPath}`);
}

createPresentation();

