const pptxgen = require('pptxgenjs');
const fs = require('fs');

async function createPresentation() {
    let pres = new pptxgen();
    pres.layout = 'LAYOUT_WIDE'; 

    // Vibrant Theme: Ocean Gradient (Deep Content, Colorful)
    const primaryDark = '065A82'; // Deep Blue
    const secondaryTeal = '1C7293'; // Teal
    const accentMint = '02C39A'; // Mint
    const textColorLight = 'FFFFFF'; 
    const textColorPrimary = '21295C'; // Midnight for high contrast

    const titleFont = { size: 44, bold: true, color: textColorLight, fontFace: 'Cambria' };
    const subTitleFont = { size: 24, color: textColorLight, fontFace: 'Calibri' };
    const sectionTitleFont = { size: 32, bold: true, color: textColorLight, fontFace: 'Cambria' };
    const bodyFont = { size: 16, color: textColorLight, fontFace: 'Calibri', margin: 0, breakLine: true };
    const tableHeaderFont = { size: 18, bold: true, color: textColorLight, fontFace: 'Calibri', align: 'center' };
    const tableBodyFont = { size: 14, color: textColorPrimary, fontFace: 'Calibri', margin: 0 };


    // --- Slide 1: Title Slide (Deep Blue Background) ---
    let slide1 = pres.addSlide();
    slide1.bkgd = primaryDark;
    slide1.addText('Incredible India: A Dynamic Transformation', { x: 0, y: 2.5, w: '100%', align: 'center', ...titleFont });
    slide1.addText('Economy, History, and Future Prospects | Presented by TITAN', { x: 0, y: 3.5, w: '100%', align: 'center', ...subTitleFont });

    // --- Slide 2: Economic History: From License Raj to LPG (Table & Content) ---
    let slide2 = pres.addSlide();
    slide2.bkgd = primaryDark;
    slide2.addText('Economic History: The 1991 Reforms', { x: 0.5, y: 0.5, w: '90%', ...sectionTitleFont });

    const historyText = "India's journey transformed from a socialist-inspired 'License Raj' (post-1947) characterized by central planning and protectionism, which led to slow growth and bureaucracy. The pivotal moment arrived with the 1991 crisis, triggering sweeping Liberalization, Privatization, and Globalization (LPG) reforms.";
    slide2.addText(historyText, { x: 0.5, y: 1.5, w: '90%', ...bodyFont, fontSize: 14 });

    const tableData = [
        [{ text: "Phase", options: { fill: secondaryTeal } }, { text: "Period", options: { fill: secondaryTeal } }, { text: "Key Characteristics", options: { fill: secondaryTeal } }, { text: "Impact", options: { fill: secondaryTeal } }],
        ["Colonial Rule", "Pre-1947", "Supplier of raw materials, Deindustrialization", "Decline in world economy share (23% to 4.2%)"],
        ["License Raj", "1947-1991", "Central Planning, State-led growth, Protectionism", "Slow growth (~1% per capita), Red tape, Shortages"],
        ["LPG Reforms", "Post-1991", "Liberalization, Privatization, Globalization", "One of world's fastest-growing, Dynamic market economy"]
    ];

    slide2.addTable(tableData, { 
        x: 0.5, y: 3.8, w: '90%', 
        border: { pt: 1, color: textColorLight },
        fill: { color: lightBg },
        cellStyle: { padding: 0.1, ...tableBodyFont },
        colW: [1.8, 1.8, 5, 4]
    });


    // --- Slide 3: Current State & Demographic Dividend (Colorful Stat Callouts) ---
    let slide3 = pres.addSlide();
    slide3.bkgd = primaryDark;
    slide3.addText('Current State & Demographic Dividend', { x: 0.5, y: 0.5, w: '90%', ...sectionTitleFont });

    slide3.addText('Fastest-Growing', { x: 0.5, y: 1.8, w: '30%', align: 'center', ...titleFont, fontSize: 48, color: accentMint });
    slide3.addText('Major Economy', { x: 0.5, y: 2.8, w: '30%', align: 'center', ...bodyFont, fontSize: 18 });

    slide3.addText('65%+ Youth', { x: '35%', y: 1.8, w: '30%', align: 'center', ...titleFont, fontSize: 48, color: accentMint });
    slide3.addText('Demographic Dividend', { x: '35%', y: 2.8, w: '30%', align: 'center', ...bodyFont, fontSize: 18 });

    const currentText = "A dynamic market economy fueled by a massive demographic dividend, positioning India as a crucial player in global economic trends.";
    slide3.addText(currentText, { x: 0.5, y: 4.5, w: '90%', ...bodyFont, fontSize: 14 });


    // --- Slide 4: Future Prospects & Key Challenges (Two Column with Bullets) ---
    let slide4 = pres.addSlide();
    slide4.bkgd = primaryDark;
    slide4.addText('Future Prospects & Challenges', { x: 0.5, y: 0.5, w: '90%', ...sectionTitleFont });

    const prospects = ["Sustained Growth Path", "Global Geopolitical Influence", "Digital Economy & Innovation Hub", "Infrastructure Development"];
    const challenges = ["Job Creation & Skill Gap", "Inequality & Regional Disparities", "Infrastructure Bottlenecks", "Energy Transition & Sustainability"];

    slide4.addText('Prospects:', { x: 0.5, y: 1.5, w: '45%', ...subTitleFont, fontSize: 24, color: accentMint });
    slide4.addText(prospects.map(t => ({ text: t, options: { ...bodyFont, fontSize: 16, bullet: true, breakLine: true } })), { x: 0.5, y: 2.2, w: '45%', h: 3 });

    slide4.addText('Challenges:', { x: '50%', y: 1.5, w: '45%', ...subTitleFont, fontSize: 24, color: accentMint });
    slide4.addText(challenges.map(t => ({ text: t, options: { ...bodyFont, fontSize: 16, bullet: true, breakLine: true } })), { x: '50%', y: 2.2, w: '45%', h: 3 });


    // --- Slide 5: Conclusion (Deep Blue) ---
    let slide5 = pres.addSlide();
    slide5.bkgd = primaryDark;
    slide5.addText('Conclusion: Resilient & Dynamic', { x: 0, y: 2.5, w: '100%', align: 'center', ...titleFont });
    slide5.addText('Continuous policy innovation crucial for inclusive and sustainable development.', { x: 0, y: 3.5, w: '100%', align: 'center', ...subTitleFont });


    const outputPath = 'C:/Users/achal/Desktop/India_Presentation_V2.pptx';
    pres.writeFile({ fileName: outputPath });
    console.log(`Presentation saved to ${outputPath}`);
}

createPresentation();

